import { action } from "solid-js";

const go = (cb) => {
  void action(function* () {
    if (typeof cb === "function") cb();
  })();
};
export const typedStep = (cb) => go(cb);
export const makeHandle = () => ({ dispose: () => go() });
export const makeVoid = () => () => go();
export const listener = { handleEvent: () => go() };
